// Generated by `pnpm nx g @app/generators:action connections.update`. Requests go through the real router
// with createTestEngine().inject. They fail until createConnectionsUpdateAction is implemented; do not weaken them.
import { connectionsUpdate } from '@app/contracts';
import { createRoleAuthorizer } from '@app/kernel';
import {
  createConnectionsUpdateAction,
  createConnectionsFakeDeps,
} from '@app/svc-connections';
import { afterEach, describe, expect, it } from 'vitest';

import { createTestEngine, type TestEngine } from '../create-test-engine.ts';

const subject = () =>
  createConnectionsUpdateAction(
    createConnectionsFakeDeps({ ownerId: 'local-token' }),
  );
const def = connectionsUpdate;
const KEY = 'generated-spec-key-0001';
let engine: TestEngine;

afterEach(async () => {
  await engine.close();
});

describe('PATCH /connections/{cid}', () => {
  it('GP-1 the route runs connections.update and answers in the shape of the contract', async () => {
    engine = createTestEngine({ actions: [subject()] });
    engine.arm('c1');
    const answer = await engine.inject({
      method: 'PATCH',
      path: '/connections/c1',
      payload: { name: 'Renamed' },
      headers: { 'idempotency-key': KEY },
    });

    expect(answer.statusCode).toBe(200);
    expect(def.output.safeParse(answer.json()).success).toBe(true);
  });

  it('GP-2 a request without the launch token is refused and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'PATCH',
      path: '/connections/c1',
      authenticated: false,
    });

    expect(answer.statusCode).toBe(401);
    expect(engine.audit.attempts).toEqual([]);
  });

  it('GP-3 a caller that does not hold connection.manage gets 403 and nothing runs', async () => {
    engine = createTestEngine({
      actions: [subject()],
      authorizer: createRoleAuthorizer({}),
    });
    engine.arm('c1');
    const answer = await engine.inject({
      method: 'PATCH',
      path: '/connections/c1',
      payload: { name: 'Renamed' },
      headers: { 'idempotency-key': KEY },
    });

    expect(answer.statusCode).toBe(403);
    expect(answer.json()).toMatchObject({ code: 'FORBIDDEN_RBAC' });
    expect(engine.audit.attempts).toEqual([]);
    expect(engine.writeCalls).toEqual([]);
  });

  it('GP-4 input that breaks the contract is a 400 Problem and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });
    engine.arm('c1');
    const answer = await engine.inject({
      method: 'PATCH',
      path: '/connections/c1',
      payload: { unexpected: true },
      headers: { 'idempotency-key': KEY },
    });

    expect(answer.statusCode).toBe(400);
    expect(answer.json()).toMatchObject({ code: 'VALIDATION_FAILED' });
    expect(engine.audit.attempts).toEqual([]);
  });

  it('GP-5 another method on the same path is 405', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'PUT',
      path: '/connections/c1',
    });

    expect(answer.statusCode).toBe(405);
    expect(answer.headers.allow).toBe('PATCH, DELETE, GET');
  });
});
